/* Define CSS variables for consistent styling */
:root {
  --background: #f4f4f9;
  --surface: #fff;
  --text: #000;
  --muted: #666;
  --border: 1px solid #ccc;
  --accent: #007bff;
  --spacing: 1rem;
}

/* Responsive pricing section */
.pricing-section {
  display: grid;
  gap: 2rem;
  max-width: 1200px;
  margin: 0 auto;
  padding: 4rem 0;
  background-color: var(--background);
}

/* Plan card styles */
.plan-card {
  background-color: var(--surface);
  border: var(--border);
  border-radius: 0.5rem;
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  overflow: hidden;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
}

/* Highlight the middle plan card */
.plan-card:nth-child(2) {
  box-shadow: 0 0 20px rgba(0, 0, 0, 0.2);
}

/* Plan card content */
.plan-card-content {
  padding: 2rem;
  text-align: center;
}

.plan-card-title {
  font-size: 1.5rem;
  font-weight: bold;
  color: var(--text);
}

.plan-card-price {
  font-size: 2rem;
  font-weight: bold;
  color: var(--accent);
}

.plan-card-features {
  list-style: none;
  padding: 0;
}

.plan-card-feature {
  font-size: 1rem;
  color: var(--muted);
}

/* Responsive adjustments */
@media (max-width: 768px) {
  .pricing-section {
    gap: 1rem;
  }
  .plan-card {
    border-radius: 0.3rem;
  }
}

/**
 * Debounce function that limits the execution of a function to once per wait period.
 * @param {Function} func - The function to debounce.
 * @param {number} wait - The time in milliseconds to wait before executing the function.
 * @returns {Function} The debounced function.
 */
function debounce(func, wait) {
  let timeout;
  return function(...args) {
    clearTimeout(timeout);
    timeout = setTimeout(() => func.apply(this, args), wait);
  };
}

/**
 * Throttle function that limits the execution of a function to at most once per wait period.
 * @param {Function} func - The function to throttle.
 * @param {number} wait - The time in milliseconds to wait before executing the function.
 * @returns {Function} The throttled function.
 */
function throttle(func, wait) {
  let lastExecuted = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastExecuted >= wait) {
      func.apply(this, args);
      lastExecuted = now;
    }
  };
}

// Demo
const log = console.log.bind(console);
const debouncedLog = debounce(log, 1000);
const throttledLog = throttle(log, 500);

// Simulate events
function simulateEvent() {
  log('Event triggered');
}

document.addEventListener('click', debouncedLog);
document.addEventListener('scroll', throttledLog);

// Simulate events
for (let i = 0; i < 10; i++) {
  simulateEvent();
}
